public class StackDemo {
    public void doStuff() {
        boolean b = true;      // 在 doStuff 的栈帧里
        go(4);                 // go 被压到栈顶，doStuff 暂时被压在下面
        System.out.println("回到 doStuff，b = " + b);   // go 弹走后，b 又可见
    }
    public void go(int x) {
        int z = x + 24;        // 参数 x、局部变量 z 都在 go 的栈帧里
        crazy();               // crazy 被压到最顶上
        System.out.println("回到 go，z = " + z);
    }
    public void crazy() {
        char c = 97;           // 在 crazy 的栈帧里，方法一结束 c 就没了
    }
    public void read() {
        int s = 42;
        sleep();
        System.out.println(s); // 回到 read，s 又可见了
    }
    public void sleep() {
        // s = 7;  // 编译错误：sleep 的栈帧里根本没有 s
    }
}

public class LifeAndScope {
    public void doStuff() {
        boolean b = true;      // b 出生：活着，且在 doStuff 作用域内
        go(4);                 // go 压栈后：b 活着，但不在作用域内
        System.out.println(b); // go 弹栈后：b 又回到作用域，可以打印
    }
    public void go(int x) {
        int z = x + 24;        // x、z 活着且在 go 作用域内
        crazy();               // crazy 压栈后：x、z 活着但不在作用域内
        System.out.println(z); // crazy 弹栈后：z 又可用
    }
    public void crazy() {
        char c = 'a';          // c 活着且在作用域内；方法一结束，c 又死又出作用域
    }
    public void read() {
        int s = 42;            // s 只在 read 的作用域内
        sleep();               // sleep 运行期间：s 活着但不在作用域内
        System.out.println(s); // 回到 read：s 又可见
    }
    public void sleep() {
        // s = 7;              // 编译错误：sleep 的作用域里没有 s
    }
}

