// 本章核心模型（Ryan-Monica 的犯罪现场）：
// 读共享数据 → 基于读到的旧值做决定 → 写回共享数据
//   Ryan  : 读 100 → 判断 100>=50 → 写回 50
//   Monica: 读 100(旧值!) → 判断 100>=100 → 写回 0   → 透支！
//
// 关键：查余额和扣钱之间有时间空档，另一条线程能钻进来
// 根源：两条以上线程访问同一个对象的数据（堆上共享对象）
// 线程「被打晕」：被切走时无感知，切回来从冻结点继续，不知数据已被改
// 并发 concurrency ≠ 并行 parallelism：多线程制造并发，是否并行看硬件核数
// 竞态条件 race condition：结果依赖不确定的线程时序

// 三个类：数据类 BankAccount / 任务类 RyanAndMonicaJob / 测试类 RyanAndMonicaTest
BankAccount account = new BankAccount();              // 只有一个账户！两条线程共享它
RyanAndMonicaJob ryan = new RyanAndMonicaJob("Ryan", account, 50);
RyanAndMonicaJob monica = new RyanAndMonicaJob("Monica", account, 100);
ExecutorService executor = Executors.newFixedThreadPool(2);
executor.execute(ryan); executor.execute(monica); executor.shutdown();

class RyanAndMonicaJob implements Runnable {
  private void goShopping(int amount) {
    if (account.getBalance() >= amount) {   // 查余额（读）
      account.spend(amount);                // 扣钱（写）—— 读和写之间有空档！
    }
  }
}
class BankAccount {
  private int balance = 100;                // private：强迫修改经过方法，才有机会保护
  public void spend(int amount) {
    balance = balance - amount;
    if (balance < 0) System.out.println("Overdrawn!"); // 故意留的报警器
  }
}
// 非确定性：一次运行透支，另一次可能正确 —— 取决于调度时序
// 结论：正确性不能靠「跑几遍没事」，要靠分析所有交错

// 并发问题三类性质：
// ① 原子性 atomicity：操作被插队（balance++、查+扣）→ 工具：synchronized、AtomicXXX(CAS)
// ② 可见性 visibility：改了别人看不到（停止标志）→ 工具：volatile、synchronized
// ③ 有序性 ordering：指令重排被别人看出来（data/ready）→ 工具：volatile、synchronized

// volatile 的真实边界：
volatile boolean stop = false;   // 对：一个写多个读的状态标志，写完立刻可见
// volatile int count = 0; count++;  // 错！volatile 不保原子，++ 三步仍丢更新 → 用 AtomicInteger

// 停止标志可见性问题：线程A while(!stop){...}，线程B stop=true
// 没 volatile：A 可能永远读缓存旧值、或 JIT 优化成 while(true)
// 有序性问题：A: data=42; ready=true;  B: if(ready) print(data);
//   重排后 ready 先写 → B 读到 ready=true 但 data=0；volatile ready 禁止这种重排
//
// synchronized 三者全包（原子+可见+有序，happens-before）；volatile 只管可见+部分有序
// 原子变量专注单值原子（内部 volatile + CAS）
// 分析任何并发问题先问：这是原子性、可见性还是有序性出了问题？再选工具

// 反例：看着符合四条，其实不是真不可变
public final class Config {
  private final List<String> hosts;
  public Config(List<String> hosts) { this.hosts = hosts; }      // 直接存外部引用！
  public List<String> getHosts() { return hosts; }               // 直接返回内部引用！
}
// 漏洞：外部可 hosts.add("evil")；可 getHosts().add(...)

// 正确：防御性复制 + 不可修改视图 + 元素本身不可变
public Config(List<String> hosts) { this.hosts = List.copyOf(hosts); } // 复制成不可修改
public List<String> getHosts() { return hosts; }   // hosts 已不可修改，返回安全
